import {coreWorkBank as bank042,coreWorkQuestions as questions042,coreWorkStatus as status042} from './core-work-042.js';
import {definingWorkBank} from './defining-work-bank.js';
export const coreWorkBank=definingWorkBank;
export function coreWorkQuestions(id,{coreVersion='0.44.0'}={}){if(coreVersion==='0.42.0')return questions042(id);return (coreWorkBank[id]?.questions||[]).map(q=>({...q,kind:'core-work',options:[{id:'yes',text:'Yes, I would like to learn this work',careerIds:[id]},{id:'no',text:'This work does not interest me',careerIds:[]}]}));}
export function cleanCoreWork(raw){const known=new Set([...Object.keys(bank042).flatMap(id=>questions042(id)),...Object.keys(coreWorkBank).flatMap(id=>coreWorkQuestions(id))].map(q=>q.id)),out={};for(const[id,a]of Object.entries(raw||{}))if(known.has(id)&&['yes','no','unsure','unfamiliar'].includes(a?.response))out[id]={response:a.response,confidence:['high','medium','low'].includes(a.confidence)?a.confidence:'high',source:a.source==='profile-inferred'?'profile-inferred':'student',evidence:typeof a.evidence==='string'?a.evidence.slice(0,1800):''};return out;}
export function coreWorkStatus(s,id){if(s._coreWorkVersion==='0.42.0')return status042(s,id);const questions=coreWorkQuestions(id),answers=questions.map(q=>s.profileJourney?.coreWork?.[q.id]),supports=a=>a?.response==='yes'&&(a.source!=='profile-inferred'||['high','medium'].includes(a.confidence)),confirmed=questions.length===2&&answers.every(supports),declined=answers.some(a=>a?.response==='no'),unfamiliar=answers.some(a=>a?.response==='unfamiliar'),inferred=answers.some(a=>a?.source==='profile-inferred'),next=questions.find((q,i)=>!supports(answers[i]))||questions[0];return {version:'0.44.0',confirmed,declined,inferred,code:confirmed?'confirmed':declined?'not-interested':unfamiliar?'unfamiliar':'needs-confirmation',headline:confirmed?(inferred?'Profile supports defining work interests':'Defining work interests confirmed'):declined?'Defining work interest is not supported':'Needs confirmation of defining work',detail:confirmed?(inferred?'Two separate defining interests have profile evidence, alongside the broader task and role checks. These simulated answers support an interest match, not a recorded student choice or proof of readiness.':'Two separate defining interests support this option, alongside the broader profile, task and role checks.'):declined?'An essential part of the work did not appeal. Adjacent interests alone do not establish this profession as a Top match.':'We need clearer interest in the defining work. Unfamiliar or uncertain work remains open to explore; tools and specialist duties are not universal interest requirements.',nextQuestionId:next?.id,questions:questions.map((q,i)=>({...q,answer:answers[i]||null}))};}
